@page "/chat"
@using sv_24546a305491494d9bf9826add83c455.Components.Chat
@using sv_24546a305491494d9bf9826add83c455.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <aside class="chat-sidebar">
        <ChannelList Channels="_channels"
                     ActiveChannelId="_activeChannelId"
                     OnChannelSelected="SelectChannel" />
    </aside>

    <main class="chat-main @(_threadOpen ? "" : "chat-main-expanded")">
        <MessageArea Channel="_activeChannel"
                     Messages="_messages"
                     ThreadSummaries="_threadSummaries"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="HandleSendMessage"
                     OnLoadMore="LoadOlderMessages" />
    </main>

    @if (_threadOpen)
    {
        <aside class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnReply="HandleThreadReply" />
        </aside>
    }
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<ThreadSummary> _threadSummaries = [];

    private int _activeChannelId;
    private Channel? _activeChannel;

    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    private int _messageSkip;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();

        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messageSkip = 0;
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messageSkip = _messages.Count;
        _threadSummaries = BuildThreadSummaries(_messages);

        await ChatService.MarkChannelReadAsync(channelId);
        CloseThread();

        // Refresh channel list to update unread counts
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadOlderMessages()
    {
        if (_activeChannel is null) return;

        var olderMessages = await ChatService.GetMessagesAsync(_activeChannelId, _messageSkip, PageSize);
        if (olderMessages.Count > 0)
        {
            _messages.InsertRange(0, olderMessages);
            _messageSkip += olderMessages.Count;
            _threadSummaries = BuildThreadSummaries(_messages);
        }
    }

    private async Task HandleSendMessage(string content)
    {
        if (_activeChannel is null) return;

        var message = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(message);
    }

    private async Task OpenThread(int rootMessageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (_threadRootMessage is null) return;

        _threadReplies = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task HandleThreadReply(string content)
    {
        if (_threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update thread summaries in main view
        _threadSummaries = BuildThreadSummaries(_messages, _threadRootMessage.Id, _threadReplies.Count);
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);

        // Refresh messages to show updated reactions
        _messages = await ChatService.GetMessagesAsync(_activeChannelId, 0, _messageSkip);
    }

    private List<ThreadSummary> BuildThreadSummaries(List<Message> messages, int? updatedThreadId = null, int? updatedCount = null)
    {
        var replies = messages.Where(m => m.ReplyToId is not null).ToList();
        var summaries = replies
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();

        if (updatedThreadId is not null && updatedCount is not null)
        {
            var existing = summaries.FirstOrDefault(s => s.RootMessageId == updatedThreadId);
            if (existing is not null)
            {
                summaries.Remove(existing);
            }
            summaries.Add(new ThreadSummary(updatedThreadId.Value, updatedCount.Value, DateTime.Now));
        }

        return summaries;
    }
}

